import 'package:flutter/material.dart';
import '../services/supabase_service.dart';
import 'profile_screen.dart';
import 'settings_screen.dart';
class HomeScreen extends StatefulWidget { const HomeScreen({super.key}); @override State<HomeScreen> createState()=>_HomeScreenState(); }
class _HomeScreenState extends State<HomeScreen>{int tab=0;Map<String,dynamic>? data; @override void initState(){super.initState();load();} Future<void> load()async{try{data=await SupabaseService.profile();}catch(_){}if(mounted)setState((){});}
 Widget tile(String title,String sub,IconData icon,Color c,String msg)=>Card(color:const Color(0xFF171525),child:ListTile(leading:CircleAvatar(backgroundColor:c.withOpacity(.2),child:Icon(icon,color:c)),title:Text(title,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(sub,style:const TextStyle(color:Colors.white60)),trailing:const Icon(Icons.chevron_right),onTap:()=>showDialog(context:context,builder:(_)=>AlertDialog(title:Text(title),content:Text(msg),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('OK'))])));
 Widget lobby()=>ListView(padding:const EdgeInsets.all(18),children:[Row(children:[const Expanded(child:Text('MEME HUNT',style:TextStyle(fontWeight:FontWeight.w900,fontSize:22,letterSpacing:2))),IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const SettingsScreen())),icon:const Icon(Icons.settings))]),Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xFF4C1D95),Color(0xFF17112B)]),borderRadius:BorderRadius.circular(22)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('WELCOME, ${(data?['username']??'PLAYER').toString().toUpperCase()}',style:const TextStyle(color:Colors.white70)),const SizedBox(height:10),const Text('Ready for the\nMeme Battle?',style:TextStyle(fontSize:27,fontWeight:FontWeight.w900)),const SizedBox(height:12),Text('LEVEL ${data?['level']??1}   •   XP ${data?['xp']??0}   •   ${data?['rank_name']??'Bronze'}')]),const SizedBox(height:22),const Text('GAME MODES',style:TextStyle(color:Color(0xFFBCA7EA),fontWeight:FontWeight.bold)),const SizedBox(height:10),tile('Play Online','Find a random opponent',Icons.bolt,Colors.purple,'Online matchmaking will be built in Phase 4.'),tile('Play With Friends','Private room and code',Icons.people,Colors.blue,'Private rooms will be built in Phase 4.'),tile('Ranked Battle','Fight for ELO',Icons.emoji_events,Colors.orange,'Ranked matches are not ready yet.'),tile('Practice Mode','Learn to play',Icons.school,Colors.teal,'Practice mode will be implemented with the game engine.'),tile('Meme Collection','Browse memes',Icons.collections,Colors.pink,'Meme library will be added in Phase 3.'),tile('Leaderboard','Top players',Icons.leaderboard,Colors.amber,'Leaderboard will be added in Phase 6.')]);
 @override Widget build(BuildContext context){final pages=[lobby(),const Center(child:Text('Meme Collection — Phase 3')),const Center(child:Text('Leaderboard — Phase 6')),ProfileScreen(profile:data)];return Scaffold(body:SafeArea(child:pages[tab]),bottomNavigationBar:NavigationBar(backgroundColor:const Color(0xFF11101B),selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const [NavigationDestination(icon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.collections),label:'Memes'),NavigationDestination(icon:Icon(Icons.emoji_events),label:'Ranks'),NavigationDestination(icon:Icon(Icons.person),label:'Profile')]));}
